VFT-C1.code:
@layer components {
  .status-badge {
    display: inline-flex;
    align-items: center;
    padding-block: var(--shelf-status-badge-paddingBlock);
    padding-inline: var(--shelf-status-badge-paddingInline);
    border-radius: var(--shelf-status-badge-borderRadius);
    background-color: var(--shelf-status-badge-bgColor-default);
    color: var(--shelf-status-badge-fgColor-default);
    font-size: var(--shelf-status-badge-fontSize);
    font-weight: var(--shelf-status-badge-fontWeight);
    line-height: var(--shelf-status-badge-lineHeight);
  }

  .status-badge--read {
    background-color: var(--shelf-status-badge-bgColor-read);
    color: var(--shelf-status-badge-fgColor-read);
  }

  .status-badge--reading {
    background-color: var(--shelf-status-badge-bgColor-reading);
    color: var(--shelf-status-badge-fgColor-reading);
  }

  .status-badge--want-to-read {
    background-color: var(--shelf-status-badge-bgColor-wantToRead);
    color: var(--shelf-status-badge-fgColor-wantToRead);
  }
}
